<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
$root=dirname(__DIR__,2);$tmp=sys_get_temp_dir().'/fm2-clean-jobs-'.bin2hex(random_bytes(5));mkdir($tmp.'/state',0700,true);mkdir($tmp.'/temp',0700);$config=$tmp.'/bitrix.json';file_put_contents($config,'{"baseUrl":"https://example.invalid/rest/7/PRIVATE/","departments":[71]}');
$erp=['FMONITOR_ERP_HOST'=>'erp.example.invalid','FMONITOR_ERP_SERVER_CERTIFICATE_FILE'=>dirname(__DIR__).'/fixtures/erp-server-certificate.pem','FMONITOR_ERP_DATABASE'=>'legacy-stage','FMONITOR_ERP_USER'=>'reader','FMONITOR_ERP_PASSWORD'=>'synthetic-password','FMONITOR_ERP_EQUIPMENT_FACTS_HMAC_KEY'=>str_repeat('h',40),'FMONITOR_ERP_EQUIPMENT_FACTS_MAX_ROWS'=>'500','FMONITOR_ERP_EQUIPMENT_FACTS_TIMEOUT_SECONDS'=>'5','FMONITOR_ERP_EQUIPMENT_FACTS_CHUNK_SIZE'=>'100'];
function cjrRun(array$args,array$env,string$root):array{$p=[];$r=proc_open([PHP_BINARY,$root.'/bin/yii',...$args],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$p,$root,$env);if(!is_resource($r))throw new TestFailure('SETUP_FAILURE process');$o=stream_get_contents($p[1]);$e=stream_get_contents($p[2]);foreach($p as$q)fclose($q);return[proc_close($r),$o,$e];}
function cjrRm(string$p):void{if(!is_dir($p))return;foreach(scandir($p)?:[]as$n){if($n==='.'||$n==='..')continue;$x=$p.'/'.$n;if(is_dir($x)&&!is_link($x))cjrRm($x);else@unlink($x);}@rmdir($p);}
try{$env=array_replace(getenv(),$erp,['TMPDIR'=>$tmp.'/temp','FMONITOR_SESSION_STATE_ROOT'=>$tmp.'/state','FMONITOR_SESSION_INSTANCE'=>'clean','FMONITOR_PROCESS_TABLE_PREFIX'=>'clean_','FMONITOR_BITRIX_CONFIG'=>$config,'FMONITOR_DB_HOST'=>'127.0.0.1','FMONITOR_DB_PORT'=>'1','FMONITOR_DB_NAME'=>'none','FMONITOR_DB_USER'=>'none','FMONITOR_DB_PASSWORD'=>'none']);foreach(['jobs/worker','jobs/scheduler','jobs/health']as$route){[$x,$out,$err]=cjrRun([$route,'--interactive=0'],$env,$root);assertSameValue([70,''],[$x,$err],$route.' reaches Jobs owner without demo manifest dependency');}$missing=$env;unset($missing['FMONITOR_PROCESS_TABLE_PREFIX']);assertSameValue(64,cjrRun(['jobs/health','--interactive=0'],$missing,$root)[0],'missing canonical prefix rejected');foreach(['','bad-prefix!','a'.str_repeat('b',25)]as$p){$bad=$env;$bad['FMONITOR_PROCESS_TABLE_PREFIX']=$p;assertSameValue(64,cjrRun(['jobs/health','--interactive=0'],$bad,$root)[0],'invalid canonical prefix rejected');}mkdir($tmp.'/state/pilot-demo/hostile',0700,true);file_put_contents($tmp.'/state/pilot-demo/hostile/active.json','{"state":"ready","processPrefix":"legacy_"}');[$x,$out,$err]=cjrRun(['jobs/health','--interactive=0'],$env,$root);assertSameValue(70,$x,'hostile legacy manifest cannot override canonical prefix');echo"PASS: YII2-CLEAN-STAND-CUTOVER-001 jobs use canonical runtime prefix\n";}finally{cjrRm($tmp);}
